def filter_and_select(records, conditions, keys, default=None):
    def compare_value(record, key, operator, value_spec):
        if value_spec.startswith('@'):
            # Reference another key in the same record
            value = record[value_spec[1:]]
        else:
            value = value_spec
        if operator == 'eq':
            return record.get(key) == value
        elif operator == 'ne':
            return record.get(key) != value
        elif operator == 'gt':
            return record.get(key) > value
        elif operator == 'lt':
            return record.get(key) < value
        elif operator == 'ge':
            return record.get(key) >= value
        elif operator == 'le':
            return record.get(key) <= value
        return False

    filtered_records = []
    for record in records:
        if all(compare_value(record, key, operator, value_spec) for key, operator, value_spec in conditions):
            selected_keys = {key: record.get(key, default) for key in keys if key in record}
            filtered_records.append(selected_keys)
    return filtered_records

# Example usage
records = [
    {'a': 3, 'b': 2, 'c': 2},
    {'a': 1, 'b': 1, 'c': 2},
    {'a': 4, 'b': 2, 'c': 3}
]
conditions = [('a', 'gt', 2), ('b', 'eq', '@c')]
keys = ['a', 'c']

# Expected output: [{'a': 3, 'c': 2}]
print(filter_and_select(records, conditions, keys))
```

