class ProcessError(Exception):
    def __init__(self, errors):
        self.errors = errors
        super().__init__(self.errors[0] if self.errors else '')

def process_commands(commands):
    results = []
    errors = []

    def convert_to_float(value):
        try:
            return float(value)
        except ValueError:
            raise ValueError(f'Invalid number: {value}')

    for command in commands:
        try:
            op, a, b = command.lower().split()
            a = convert_to_float(a)
            b = convert_to_float(b)

            if op == 'add':
                results.append(a + b)
            elif op == 'subtract':
                results.append(a - b)
            elif op == 'multiply':
                results.append(a * b)
            elif op == 'divide':
                if b == 0:
                    raise ZeroDivisionError('Division by zero')
                results.append(a / b)
            else:
                raise ValueError(f'Unknown operation: {op}')
        except ValueError as e:
            errors.append(str(e))
        except ZeroDivisionError as e:
            errors.append(str(e))

    if errors:
        raise ProcessError(errors)

    return results

# Example usage:
commands = [
    "add 1.5 2.5",
    "subtract 4.0 2.0",
    "multiply 3.0 4.0",
    "divide 10.0 0.0",  # This will cause a division by zero error
    "unknown 5.0 3.0"   # This will cause an unknown operation error
]

try:
    result = process_commands(commands)
    print("Results:", result)
except ProcessError as e:
    print("ProcessError:", e)
