def parse_balanced(text):
    tokens = []
    stack = []
    current_token = ''
    in_quote = False
    quote_char = None
    i = 0

    while i < len(text):
        char = text[i]

        if char in ('"', "'"):
            if in_quote and char == quote_char:
                in_quote = False
                current_token += char
            elif not in_quote:
                in_quote = True
                quote_char = char
                current_token += char
            else:
                current_token += char
        elif char in ('(', '[', '{'):
            if in_quote:
                current_token += char
            else:
                if current_token:
                    tokens.append(current_token.strip())
                    current_token = ''
                stack.append(char)
        elif char in (')', ']', '}'):
            if in_quote and char == quote_char:
                current_token += char
            elif not in_quote:
                if current_token:
                    tokens.append(current_token.strip())
                    current_token = ''
                stack.pop()
            else:
                current_token += char
        elif char.isspace() and not in_quote:
            if current_token:
                tokens.append(current_token.strip())
                current_token = ''
        else:
            current_token += char

        i += 1

    if current_token:
        tokens.append(current_token.strip())

    return tokens

# Test cases
print(parse_balanced('hello (world [foo bar]) baz'))  # ['hello', '(world [foo bar])', 'baz']
print(parse_balanced('say "hello (world)" now'))      # ['say', 'hello (world)', 'now']
print(parse_balanced('a {b (c)} d'))                 # ['a', '{b (c)}', 'd']
print(parse_balanced('unclosed (text'))              # ['unclosed', '(text']
print(parse_balanced('quote "unclosed'))             # ['quote', 'unclosed']
```

