import csv

def read_csv_safe(filepath):
    try:
        with open(filepath, mode='r', newline='') as file:
            csv_reader = csv.reader(file)
            header = next(csv_reader, None)
            if not header:
                return []

            result = []
            for row in csv_reader:
                if not row:
                    continue
                row_dict = dict(zip(header, row))
                # Pad with empty strings if row has fewer fields than header
                row_dict = {header[i]: row_dict.get(header[i], '') for i in range(len(header))}
                result.append(row_dict)

            # Handle case where file has only header and no data rows
            if not result:
                return []
            return result

    except FileNotFoundError:
        return []
    except Exception as e:
        return []
